package app.veyra;
import android.content.Context;import android.net.Uri;import androidx.media3.datasource.*;import androidx.media3.datasource.cache.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.json.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public class OfflineStoreTest {
 @Test public void offlineCacheReadsStoredBytesAndRejectsMissingResources()throws Exception{Context c=RuntimeEnvironment.getApplication();String id=UUID.randomUUID().toString();SimpleCache cache=OfflineStore.cache(c,id);Uri uri=Uri.parse("https://example.invalid/offline.mp4");byte[] bytes={1,2,3,4};CacheDataSource writing=new CacheDataSource.Factory().setCache(cache).setUpstreamDataSourceFactory(()->new ByteArrayDataSource(bytes)).createDataSource();new CacheWriter(writing,new DataSpec.Builder().setUri(uri).setLength(4).build(),null,null).cache();DataSource source=OfflineStore.readOnly(c,id).createDataSource();source.open(new DataSpec(uri));byte[] actual=new byte[4];assertEquals(4,source.read(actual,0,4));assertArrayEquals(bytes,actual);source.close();try{source.open(new DataSpec(Uri.parse("https://example.invalid/missing.mp4")));fail("An offline cache miss must fail, not use the network");}catch(java.io.IOException expected){}finally{source.close();OfflineStore.remove(c,id);}}
 @Test public void onlyCompletedPrivateRecordsCanLaunchOfflinePlayback()throws Exception{Context c=RuntimeEnvironment.getApplication();String id=UUID.randomUUID().toString();JSONObject record=new JSONObject().put("state","downloading").put("url","http://127.0.0.1:12345/resource.mp4?src=test").put("mime","video/mp4").put("title","Test");OfflineStore.save(c,id,record);try{OfflineStore.request(c,id);fail();}catch(java.io.IOException expected){}record.put("state","complete");OfflineStore.save(c,id,record);assertEquals("Test",OfflineStore.request(c,id).title);assertTrue(OfflineStore.request(c,id).contentId.startsWith("offline:"));c.getSharedPreferences("downloads",0).edit().remove(id).commit();}
 @Test public void rejectsPathTraversalIds(){try{OfflineStore.checked("../../files");fail();}catch(IllegalArgumentException expected){}}

 @Test public void hlsManifestAndSegmentsRemainReadableWithoutUpstream()throws Exception{
  Context c=RuntimeEnvironment.getApplication();String id=UUID.randomUUID().toString();String playlist="#EXTM3U\n#EXT-X-VERSION:3\n#EXT-X-TARGETDURATION:1\n#EXT-X-MEDIA-SEQUENCE:0\n#EXTINF:1,\nsegment.ts\n#EXT-X-ENDLIST\n";
  byte[] manifest=playlist.getBytes(java.nio.charset.StandardCharsets.UTF_8);byte[] segment={9,8,7,6};
  DataSource.Factory upstream=()->new DataSource(){private ByteArrayDataSource delegate;public void addTransferListener(TransferListener listener){}public long open(DataSpec spec)throws java.io.IOException{delegate=new ByteArrayDataSource(spec.uri.getPath().endsWith(".m3u8")?manifest:segment);return delegate.open(spec);}public int read(byte[] b,int o,int n)throws java.io.IOException{return delegate.read(b,o,n);}public Uri getUri(){return delegate==null?null:delegate.getUri();}public void close(){if(delegate!=null)delegate.close();}};
  CacheDataSource.Factory factory=new CacheDataSource.Factory().setCache(OfflineStore.cache(c,id)).setUpstreamDataSourceFactory(upstream);
  androidx.media3.exoplayer.offline.DownloadRequest request=new androidx.media3.exoplayer.offline.DownloadRequest.Builder(id,Uri.parse("https://example.invalid/movie.m3u8")).setMimeType("application/x-mpegURL").build();
  new androidx.media3.exoplayer.offline.DefaultDownloaderFactory(factory).createDownloader(request).download(null);
  DataSource local=OfflineStore.readOnly(c,id).createDataSource();local.open(new DataSpec(Uri.parse("https://example.invalid/segment.ts")));byte[] result=new byte[4];assertEquals(4,local.read(result,0,4));assertArrayEquals(segment,result);local.close();local.open(new DataSpec(Uri.parse("https://example.invalid/movie.m3u8")));assertTrue(local.read(new byte[512],0,512)>0);local.close();OfflineStore.remove(c,id);
 }
}
